// Synthetic demo data.
const SAMPLE = [{"issue_id":"ISS-2001","customer":"Nordhafen Logistics","process":"order_to_cash","process_step":"Billing","error_message":"Posting period 010 2026 is not open for company code 1010","description":"Billing documents cannot be released to accounting since this morning. 45 billing clerks are blocked and invoices are piling up.","users_affected":45,"revenue_at_risk_eur":250000,"blocks_period_close":false,"reported_at":"2026-11-03T07:45:00Z"},{"issue_id":"ISS-2002","customer":"Kestrel Mobility","process":"order_to_cash","process_step":"Outbound delivery","error_message":"IDoc status 51: application document not posted","description":"Outbound deliveries are created but the IDoc to the external warehouse system fails, so goods are not picked.","users_affected":8,"revenue_at_risk_eur":30000,"blocks_period_close":false,"reported_at":"2026-11-03T08:10:00Z"},{"issue_id":"ISS-2003","customer":"Tessaro Machinery","process":"plan_to_produce","process_step":"MRP run","error_message":"","description":"The nightly MRP run duration increased from 20 minutes to more than 3 hours after we extended the planning horizon. Planners start the day without current planned orders.","users_affected":12,"revenue_at_risk_eur":0,"blocks_period_close":false,"reported_at":"2026-11-03T06:30:00Z"},{"issue_id":"ISS-2004","customer":"Brightfield Foods","process":"procure_to_pay","process_step":"Create purchase order","error_message":"You are not authorized to create purchase orders for purchasing organization 1010","description":"A new buyer who joined this week cannot create purchase orders.","users_affected":1,"revenue_at_risk_eur":0,"blocks_period_close":false,"reported_at":"2026-11-03T09:00:00Z"},{"issue_id":"ISS-2005","customer":"Vantara Chemicals","process":"record_to_report","process_step":"Period-end close","error_message":"Foreign currency valuation cancelled: exchange rate type M missing for 31.10.2026","description":"The foreign currency valuation job of the October close was cancelled. Closing cannot continue until valuation has run.","users_affected":6,"revenue_at_risk_eur":0,"blocks_period_close":true,"reported_at":"2026-11-03T10:15:00Z"},{"issue_id":"ISS-2006","customer":"Orbis Medical","process":"procure_to_pay","process_step":"Supplier invoice","error_message":"","description":"How do I park a supplier invoice when the price on the invoice differs from the purchase order price? I want to save it and check with the buyer first.","users_affected":1,"revenue_at_risk_eur":0,"blocks_period_close":false,"reported_at":"2026-11-03T11:20:00Z"},{"issue_id":"ISS-2007","customer":"Lumen Retail Group","process":"hire_to_retire","process_step":"Payroll","error_message":"","description":"Payslips for October are not visible in employee self-service for store employees, although the payroll run finished yesterday.","users_affected":140,"revenue_at_risk_eur":0,"blocks_period_close":false,"reported_at":"2026-11-03T12:00:00Z"},{"issue_id":"ISS-2008","customer":"Brightfield Foods","process":"order_to_cash","process_step":"Sales order","error_message":"Credit block: credit limit exceeded","description":"All new sales orders for customer 100234 are blocked for credit although finance raised the credit limit this morning.","users_affected":3,"revenue_at_risk_eur":8000,"blocks_period_close":false,"reported_at":"2026-11-03T13:40:00Z"}];
return SAMPLE.map((json) => ({ json }));

const PROCESSES = ['order_to_cash', 'procure_to_pay', 'record_to_report', 'plan_to_produce', 'hire_to_retire', 'cross_process'];

const raw = [];
for (const item of $input.all()) {
  const body = item.json.body ?? item.json;
  if (Array.isArray(body.items)) raw.push(...body.items);
  else raw.push(body);
}

return raw
  .filter((r) => r.description || r.error_message)
  .map((r, i) => ({
    json: {
      issue_id: String(r.issue_id ?? r.id ?? `ISS-${Date.now()}-${i}`),
      customer: String(r.customer ?? 'unknown'),
      process: PROCESSES.includes(r.process) ? r.process : 'cross_process',
      process_step: String(r.process_step ?? ''),
      error_message: String(r.error_message ?? ''),
      description: String(r.description ?? ''),
      users_affected: Math.max(0, Number(r.users_affected) || 0),
      revenue_at_risk_eur: Math.max(0, Number(r.revenue_at_risk_eur) || 0),
      blocks_period_close: r.blocks_period_close === true,
      reported_at: r.reported_at ?? new Date().toISOString(),
    },
  }));

// Lightweight retrieval: token-overlap scoring against the known-issue knowledge base.
// Good enough for tens to a few hundred articles; switch to a vector store beyond that.
const KB = [{"id":"KB-001","title":"Posting period not open","process":"record_to_report","symptom":"Documents cannot be posted or released to accounting because the posting period is closed","keywords":["posting","period","open","closed","release","accounting","billing"],"root_cause_category":"configuration","resolution":"Ask the GL accountant to open the posting period for the company code and account type in Manage Posting Periods, then re-release the documents."},{"id":"KB-002","title":"IDoc status 51 on outbound delivery","process":"order_to_cash","symptom":"Outbound IDoc fails with status 51 and the external warehouse never receives the delivery","keywords":["idoc","status","51","delivery","warehouse","wms","interface","posted"],"root_cause_category":"integration","resolution":"Check the IDoc error log for the failing segment, correct the partner profile or mapping, and reprocess the IDoc. Add interface monitoring alerts so failures are not silent."},{"id":"KB-003","title":"Missing business role for purchasing organization","process":"procure_to_pay","symptom":"User is not authorized to create purchase orders for a purchasing organization","keywords":["authorized","authorization","purchase","order","purchasing","organization","role"],"root_cause_category":"authorization","resolution":"Assign the purchaser business role with the correct purchasing organization restriction via the identity and access management app; changes take effect after the next logon."},{"id":"KB-004","title":"Exchange rate missing for valuation","process":"record_to_report","symptom":"Foreign currency valuation is cancelled because an exchange rate for the key date is missing","keywords":["exchange","rate","currency","valuation","missing","type","close"],"root_cause_category":"master_data","resolution":"Maintain the missing exchange rate for the rate type and key date (or fix the automatic rate import job), then restart the valuation run."},{"id":"KB-005","title":"Long MRP runtime after planning horizon change","process":"plan_to_produce","symptom":"MRP run duration increases strongly after extending the planning horizon or scope","keywords":["mrp","run","duration","runtime","planning","horizon","planned","orders"],"root_cause_category":"performance","resolution":"Limit the planning horizon to what planners need, run net change planning instead of regenerative planning, and schedule parallel processing by plant."},{"id":"KB-006","title":"Park a supplier invoice with price variance","process":"procure_to_pay","symptom":"User asks how to save a supplier invoice without posting when the price differs from the purchase order","keywords":["park","supplier","invoice","price","differs","purchase","order","save"],"root_cause_category":"user_error","resolution":"In Create Supplier Invoice, enter the invoice and choose Save as Draft (park). The invoice can be completed after the buyer confirms the price; tolerance limits define when a payment block is set automatically."},{"id":"KB-007","title":"Payslips not visible after payroll run","process":"hire_to_retire","symptom":"Employees cannot see payslips in self-service after payroll has finished","keywords":["payslip","payslips","self","service","payroll","visible","employee"],"root_cause_category":"configuration","resolution":"Check that the payroll results were released for self-service and that the payslip publication date is not in the future; republish for the affected payroll area."},{"id":"KB-008","title":"Credit block remains after credit limit increase","process":"order_to_cash","symptom":"Sales orders stay blocked for credit even though the credit limit was raised","keywords":["credit","block","limit","exceeded","sales","order","raised","exposure"],"root_cause_category":"master_data","resolution":"Verify the new limit is saved for the correct credit segment, recalculate the credit exposure, and release existing blocked orders; new orders will be checked against the updated limit."}];
const MIN_SCORE = 0.3;
const TOP_K = 2;
const STOP = new Set(['the', 'and', 'for', 'are', 'was', 'not', 'but', 'this', 'that', 'with', 'from', 'after', 'since', 'cannot', 'our', 'they', 'how', 'when', 'what', 'all', 'has', 'have', 'into']);
const tokens = (s) => new Set(
  String(s).toLowerCase().replace(/[^a-z0-9äöüß\s]/g, ' ').split(/\s+/).filter((t) => t.length > 2 && !STOP.has(t)),
);
const KB_TOKENS = KB.map((a) => ({ article: a, tokens: tokens(`${a.title} ${a.keywords.join(' ')}`) }));

return $input.all().map(({ json }) => {
  const query = tokens(`${json.process_step} ${json.error_message} ${json.description}`);
  const kb_candidates = KB_TOKENS
    .map(({ article, tokens: kt }) => {
      const overlap = [...kt].filter((t) => query.has(t)).length;
      const score = Math.round((overlap / Math.max(1, kt.size)) * 100) / 100;
      return { id: article.id, title: article.title, root_cause_category: article.root_cause_category, resolution: article.resolution, score };
    })
    .filter((c) => c.score >= MIN_SCORE)
    .sort((a, b) => b.score - a.score)
    .slice(0, TOP_K);
  return { json: { ...json, kb_candidates } };
});

