// Severity is decided by explicit, auditable business rules, not by the LLM.
// The LLM contributes the root-cause hypothesis; rules decide impact, owner and SLA.
const ROOT_CAUSES = ['master_data', 'configuration', 'authorization', 'integration', 'performance', 'user_error', 'unknown'];
const OWNER_TEAM = {
  master_data: 'Master Data Team',
  configuration: 'Functional Consultants',
  authorization: 'Security & Roles',
  integration: 'Integration Team',
  performance: 'Operations',
  user_error: 'Key User Support',
  unknown: 'Process Expert Triage',
};
const SLA_HOURS = { P1: 4, P2: 24, P3: 72, P4: 120 };
const MIN_CONFIDENCE = 0.5;
const SELF_SERVICE_CONFIDENCE = 0.7;

const parseLlm = (json) => {
  let o = json.output ?? json.text ?? json;
  if (typeof o === 'string') {
    try { o = JSON.parse(o); } catch { return null; }
  }
  return o && typeof o === 'object' ? o : null;
};

const originals = $('Match Known Issues').all();
return $input.all().map((item, i) => {
  const src = originals[i]?.json ?? {};
  const llm = parseLlm(item.json);
  const issues = [];
  if (!llm) issues.push('unparseable_llm_output');
  const r = llm ?? {};
  if (r.issue_id && r.issue_id !== src.issue_id) issues.push('issue_id_mismatch');

  let root_cause_category = r.root_cause_category;
  if (!ROOT_CAUSES.includes(root_cause_category)) {
    issues.push('invalid_root_cause_category');
    root_cause_category = 'unknown';
  }
  const confidence = Math.min(1, Math.max(0, Number(r.confidence) || 0));
  const candidates = src.kb_candidates ?? [];
  const kb = candidates.find((c) => c.id === r.matched_kb_id) ?? null;
  if (r.matched_kb_id && !kb) issues.push('unknown_kb_id');

  const reasons = [];
  let severity;
  if (src.blocks_period_close) reasons.push('blocks period-end close');
  if (src.revenue_at_risk_eur >= 100000) reasons.push('revenue at risk >= EUR 100k');
  if (src.users_affected >= 100) reasons.push('>= 100 users affected');
  if (reasons.length) {
    severity = 'P1';
  } else if (src.users_affected >= 20 || src.revenue_at_risk_eur >= 10000) {
    severity = 'P2';
    reasons.push(src.users_affected >= 20 ? '>= 20 users affected' : 'revenue at risk >= EUR 10k');
  } else if (root_cause_category === 'user_error' && kb && confidence >= SELF_SERVICE_CONFIDENCE) {
    severity = 'P4';
    reasons.push('how-to question answered by a known article');
  } else {
    severity = 'P3';
    reasons.push('limited business impact');
  }

  const needs_human_review = issues.length > 0 || confidence < MIN_CONFIDENCE;
  const reported = new Date(src.reported_at);
  const base = Number.isNaN(reported.getTime()) ? new Date() : reported;
  const route = severity === 'P1' ? 'escalate' : severity === 'P4' && !needs_human_review ? 'self_service' : 'standard';

  return {
    json: {
      issue_id: src.issue_id,
      customer: src.customer,
      process: src.process,
      process_step: src.process_step,
      error_message: src.error_message,
      description: src.description,
      users_affected: src.users_affected,
      revenue_at_risk_eur: src.revenue_at_risk_eur,
      blocks_period_close: src.blocks_period_close,
      reported_at: src.reported_at,
      root_cause_category,
      confidence,
      matched_kb_id: kb?.id ?? null,
      kb_title: kb?.title ?? null,
      kb_resolution: kb?.resolution ?? null,
      explanation: String(r.explanation ?? ''),
      next_steps: Array.isArray(r.next_steps) ? r.next_steps.map(String) : [],
      customer_message: String(r.customer_message ?? ''),
      severity,
      severity_reasons: reasons,
      owner_team: OWNER_TEAM[root_cause_category],
      sla_due_at: new Date(base.getTime() + SLA_HOURS[severity] * 3600 * 1000).toISOString(),
      route,
      needs_human_review,
      validation_issues: issues,
    },
  };
});

